<script setup lang="ts">const route=useRoute();const token=computed(()=>String(route.params.token||""));const{post,pending,error,bookmarked,phone,note,contactLoading,actionMessage,revealContact,toggleBookmark,saveNote,submitReport}=await usePostDetail(token);const expanded=ref(false),noteOpen=ref(false),reportOpen=ref(false),noteDraft=ref(""),reportReason=ref("fraud");const visibleDescription=computed(()=>expanded.value||!post.value||post.value.description.length<180?post.value?.description:`${post.value.description.slice(0,180)}…`);async function share(){if(!post.value)return;if(navigator.share)await navigator.share({title:post.value.title,url:post.value.canonical});else await navigator.clipboard?.writeText(post.value.canonical);actionMessage.value="پیوند آگهی آماده اشتراک‌گذاری شد."}function persistNote(){saveNote(noteDraft.value);noteOpen.value=false}function report(){submitReport(({fraud:"کلاهبرداری",duplicate:"تکراری",sold:"فروخته‌شده",prohibited:"ممنوع",other:"سایر"}as Record<string,string>)[reportReason.value]||"سایر");reportOpen.value=false}const jsonLd=computed(()=>post.value?{"@context":"https://schema.org","@type":"Product",name:post.value.title,description:post.value.description,url:post.value.canonical,image:post.value.media.map(item=>item.url),areaServed:{"@type":"City",name:post.value.cityName}}:null);useSeoMeta({title:()=>post.value?`${post.value.title} | هفت‌سو`:"آگهی | هفت‌سو",description:()=>post.value?.description.slice(0,155)||"جزئیات آگهی هفت‌سو",ogTitle:()=>post.value?.title,ogDescription:()=>post.value?.description.slice(0,200),ogType:"website",ogImage:()=>post.value?.media[0]?.url});useHead(()=>({link:post.value?[{rel:"canonical",href:post.value.canonical}]:[],script:jsonLd.value?[{type:"application/ld+json",innerHTML:JSON.stringify(jsonLd.value)}]:[]}));</script>
<template><main id="main-content" class="post-page"><UiState v-if="pending" kind="loading" title="در حال دریافت آگهی" description="چند لحظه صبر کنید."/><UiState v-else-if="error||!post||post.state==='removed'" kind="error" title="این آگهی در دسترس نیست" description="ممکن است حذف شده باشد یا نشانی آن تغییر کرده باشد." action-label="بازگشت به آگهی‌ها" @action="navigateTo('/s/isfahan')"/><div v-else class="post-shell"><nav class="breadcrumb" aria-label="مسیر صفحه"><NuxtLink to="/">هفت‌سو</NuxtLink><span>‹</span><NuxtLink :to="`/s/${post.cityKey}/${post.categorySlug}`">{{ post.cityName }}</NuxtLink><span>‹</span><span aria-current="page">{{ post.neighborhoodNames.join('، ') }}</span></nav><div v-if="post.state==='expired'" class="post-state-banner">این آگهی منقضی شده و اطلاعات تماس آن نمایش داده نمی‌شود.</div><div class="post-detail-grid"><div><PostGallery :media="post.media" :title="post.title"/><section class="post-section post-description"><h2>توضیحات</h2><p>{{ visibleDescription }}</p><button v-if="post.description.length>=180" class="text-button" type="button" @click="expanded=!expanded">{{ expanded?'نمایش کمتر':'نمایش کامل' }}</button></section><section v-if="post.location" class="post-section"><h2>محدوده آگهی</h2><ApproximateLocationMap :point="post.location"/></section></div><article class="post-main"><PostInteractionBar :bookmarked="bookmarked" @bookmark="toggleBookmark" @share="share" @note="noteOpen=true;noteDraft=note" @report="reportOpen=true"/><p class="post-age">منتشرشده در {{ post.cityName }}</p><h1>{{ post.title }}</h1><p class="post-place">{{ post.cityName }}، {{ post.neighborhoodNames.join('، ') }}</p><DynamicAttributeSummary :attributes="post.attributes"/><section class="seller-card"><div><strong>{{ post.seller.name }}</strong><span>{{ post.seller.verified?'هویت تأیید شده':'فروشنده شخصی' }}</span></div><small v-if="post.seller.memberSince">عضو از {{ post.seller.memberSince }}</small></section><div class="post-contact-actions"><button class="button button-primary" type="button" :disabled="post.state==='expired'||!post.contact.canRevealPhone||contactLoading" @click="revealContact">{{ contactLoading?'در حال دریافت…':phone?'شماره تماس':'نمایش شماره تماس' }}</button><NuxtLink v-if="post.contact.chatEnabled" class="button button-secondary" :to="`/chat/${post.token}`">ارسال پیام</NuxtLink></div><div v-if="phone" class="revealed-contact" role="status"><span>شماره فروشنده</span><a :href="`tel:${phone}`" dir="ltr">{{ phone }}</a></div><PostSafetyPanel/></article></div><p v-if="actionMessage" class="post-action-message" role="status">{{ actionMessage }}</p></div><Teleport to="body"><div v-if="noteOpen" class="post-dialog-backdrop" @click.self="noteOpen=false"><form class="post-dialog" @submit.prevent="persistNote"><h2>یادداشت خصوصی</h2><p>این متن فقط برای خود شما نمایش داده می‌شود.</p><textarea v-model="noteDraft" maxlength="500" rows="5"></textarea><div><button class="button button-secondary" type="button" @click="noteOpen=false">انصراف</button><button class="button button-primary">ذخیره</button></div></form></div><div v-if="reportOpen" class="post-dialog-backdrop" @click.self="reportOpen=false"><form class="post-dialog" @submit.prevent="report"><h2>گزارش آگهی</h2><label>دلیل گزارش<select v-model="reportReason"><option value="fraud">احتمال کلاهبرداری</option><option value="duplicate">آگهی تکراری</option><option value="sold">فروخته شده</option><option value="prohibited">محتوای ممنوع</option><option value="other">سایر</option></select></label><div><button class="button button-secondary" type="button" @click="reportOpen=false">انصراف</button><button class="button button-primary">ارسال گزارش</button></div></form></div></Teleport></main></template>
